sql_reference:
SELECT ROUND(AVG(total), 2) AS panier_moyen
FROM (SELECT order_id, SUM(price) AS total
      FROM entrepot.order_items GROUP BY order_id) AS t;

SELECT COUNT(*) AS commandes_multi_articles
FROM (SELECT order_id FROM entrepot.order_items
      GROUP BY order_id HAVING COUNT(*) > 1) AS t;

SELECT customer_state AS etat, COUNT(*) AS clients
FROM entrepot.customers GROUP BY customer_state
ORDER BY clients DESC, etat ASC LIMIT 5;

SELECT product_id, COUNT(*) AS articles_vendus
FROM entrepot.order_items GROUP BY product_id
ORDER BY articles_vendus DESC, product_id ASC LIMIT 10;

SELECT seller_id, ROUND(SUM(price), 2) AS chiffre_affaires
FROM entrepot.order_items GROUP BY seller_id
ORDER BY chiffre_affaires DESC LIMIT 5;

SELECT payment_type AS moyen_paiement, COUNT(*) AS utilisations
FROM entrepot.order_payments GROUP BY payment_type
ORDER BY utilisations DESC LIMIT 5;

SELECT s.seller_id, COUNT(DISTINCT s.seller_city) AS villes
FROM entrepot.sellers AS s GROUP BY s.seller_id
ORDER BY villes DESC, s.seller_id ASC LIMIT 10;

SELECT order_status AS statut, COUNT(*) AS commandes
FROM entrepot.orders GROUP BY order_status
ORDER BY commandes DESC LIMIT 3;

SELECT EXTRACT(year FROM TRY_CAST(order_purchase_timestamp AS TIMESTAMP)) AS annee,
       COUNT(*) AS commandes
FROM entrepot.orders GROUP BY 1 ORDER BY 1;

SELECT dayname(TRY_CAST(order_purchase_timestamp AS TIMESTAMP)) AS jour_semaine,
       COUNT(*) AS commandes
FROM entrepot.orders GROUP BY 1 ORDER BY commandes DESC;

